(()=>{'use strict';
const KEY='asset-client-data-v2',OLD='asset-client-data-v1';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(16).slice(2);
const money=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(Number(n)||0);
const dateNow=()=>new Date().toISOString().slice(0,10);
const typeDefaults={'Telefono cordless':21.5,'Telefono IP':0,'Router':40,'Room Bar':null,'Room Bar Pro':null,'Desk Mini':null,'Room Kit':null,'Room Kit Mini':null,'Room Kit Plus':null,'Switch':0,'Access point':0,'PC':0,'Smartphone':0,'Altro':0};
const typeIcons={'Telefono IP':['☎','#e7efff','#244f9e'],'Telefono cordless':['📞','#e4f7ed','#176642'],'Smartphone':['▯','#f0e8ff','#6941a5'],'Router':['↗','#fff0dc','#92500a'],'Switch':['⇄','#e2f6f8','#176873'],'Access point':['◉','#e8f5e9','#2d6b35'],'PC':['▣','#e9edf0','#46525d'],'Room Bar':['▰','#fce7f3','#9d2768'],'Room Bar Pro':['▰+','#f3e8ff','#6b35a6'],'Desk Mini':['▱','#e7f4ff','#205b85'],'Room Kit':['▰','#e5f3ff','#205b85'],'Room Kit Mini':['▰','#e5f3ff','#205b85'],'Room Kit Plus':['▰+','#e5f3ff','#205b85'],'Altro':['◆','#eee','#555']};
let db;
try{db=JSON.parse(localStorage.getItem(KEY))}catch{}
if(!db){let old={};try{old=JSON.parse(localStorage.getItem(OLD))||{}}catch{};db={branches:(old.branches||[]).map(b=>({...b,phonePrefix:b.phonePrefix||'',networkLan:b.networkLan||'',networkServices:b.networkServices||'',networkGuest:b.networkGuest||'',wlc:b.wlc||'',voice:b.voice||'',oldName:b.oldName||''})),devices:(old.devices||[]).map(d=>({...d,purchaseCost:Number(d.purchaseCost)||0,purchaseDate:d.purchaseDate||'',activationDate:d.activationDate||'',monthlyFee:typeDefaults[d.type]??0,usefulLifeMonths:Number(d.usefulLifeMonths)||36,replacedFrom:d.replacedFrom||'',lotId:''})),purchases:[],settings:{roomBarFee:'',roomBarProFee:''}};localStorage.setItem(KEY,JSON.stringify(db))}
db.branches ||= []; db.devices ||= []; db.purchases ||= []; db.licensePurchases ||= []; db.licenseAllocations ||= []; db.settings ||= {roomBarFee:'',roomBarProFee:''};
db.settings.monthlyLicenseFee ??= '';
db.branches.forEach(b=>{if(b.licenseFeeActive==null)b.licenseFeeActive=false});
const sortedBranches=()=>db.branches.slice().sort((a,b)=>String((a.ragioneSociale? a.ragioneSociale+' — ':'')+a.name).localeCompare(String((b.ragioneSociale? b.ragioneSociale+' — ':'')+b.name),'it',{sensitivity:'base'}));
db.branches.forEach(b=>{if(b.monthlyRevenue==null)b.monthlyRevenue=0});
let page='dashboard',editId=null,query='',deviceFilter='',selectedBranchId='';
const save=()=>localStorage.setItem(KEY,JSON.stringify(db));
const branchName=id=>db.branches.find(b=>b.id===id)?.name||'Magazzino / non assegnato';
const splitBranchName=value=>{let s=String(value||'').trim(),i=s.indexOf(' - ');return i>0?{ragioneSociale:s.slice(0,i).trim(),name:s.slice(i+3).trim()}:{ragioneSociale:'',name:s}};
const deviceBadge=t=>{let v=typeIcons[t]||typeIcons.Altro;return '<span class="device-kind" style="--kind-bg:'+v[1]+';--kind-color:'+v[2]+'"><span>'+v[0]+'</span>'+esc(t||'Altro')+'</span>'};
const statusBadge=s=>'<span class="badge '+(['Guasto','Dismesso'].includes(s)?'bad':['In riparazione','In consegna'].includes(s)?'warn':'ok')+'">'+esc(s||'—')+'</span>';
async function loadVideoSeed(){
 if(db.settings.videoSeedVersion==='2026-10-09')return;
 try{
  const response=await fetch('./video-seed.json');if(!response.ok)throw new Error('HTTP '+response.status);
  const seed=await response.json();
  let records;
  if(Array.isArray(seed))records=seed;
  else if(seed.encoding==='deflate-base64'){
   const bytes=Uint8Array.from(atob(seed.data),ch=>ch.charCodeAt(0));
   const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate'));
   records=JSON.parse(await new Response(stream).text());
  }else throw new Error('Formato video-seed.json non riconosciuto');
  const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('it').replace(/[^a-z0-9]+/g,' ').trim();
  const slug=s=>norm(s).replace(/\s+/g,'-').slice(0,40)||'sede';
  let added=0,skipped=0;const unmatched=[];
  records.forEach((row,index)=>{
   const [company,site,type,, ,status,contract]=row;
   if(!type||String(type).trim().toUpperCase()==='N/A')return;
   const branch=db.branches.find(b=>norm(b.name)===norm(site));
   if(!branch){skipped++;unmatched.push(String(site||'(filiale vuota)'));return}
   const serial='VIDEO-'+slug(company)+'-'+slug(site)+'-'+String(index+1).padStart(3,'0');
   if(db.devices.some(d=>d.videoSeedId===index+1||d.serial===serial))return;
   db.devices.push({id:uid(),videoSeedId:index+1,serial,type:String(type).trim(),brand:'Cisco',model:String(type).trim(),status:norm(status)==='ok'?'Operativo':'Disponibile',branchId:branch.id,assignedTo:'',purchaseCost:0,purchaseDate:'',activationDate:'',monthlyFee:0,usefulLifeMonths:36,replacedFrom:'',notes:contract?('Contratto: '+String(contract).trim()):'Contratto non specificato',lotId:''});added++;
  });
  if(skipped===0)db.settings.videoSeedVersion='2026-10-09';
  save();
  console.info('Sale riunioni importate:',added,'apparati; filiali non corrispondenti:',skipped);
  if(unmatched.length)console.warn('Dispositivi non importati: associare prima queste filiali nell’anagrafica:',[...new Set(unmatched)]);
  render();
 }catch(err){console.error('Caricamento apparati sale riunioni non riuscito:',err)}
}
function styles(){if($('#assetStyles'))return;let s=document.createElement('style');s.id='assetStyles';s.textContent='.dashboard-link{cursor:pointer;transition:transform .15s ease,border-color .15s ease}.dashboard-link:hover{transform:translateY(-2px);border-color:var(--primary)}.dashboard-link:focus-visible{outline:3px solid var(--primary);outline-offset:3px}.device-kind{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:9px;background:var(--kind-bg);color:var(--kind-color);font-size:.78rem;font-weight:750;white-space:nowrap}.device-cell{display:grid;gap:6px;min-width:145px}.finance-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.finance-tabs button{border:1px solid var(--border);background:var(--surface);color:var(--text);padding:10px 14px;border-radius:12px}.finance-tabs button.active{background:var(--primary);color:#fff;border-color:var(--primary)}.finance-panel[hidden]{display:none!important}.finance-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.finance-grid .card{min-width:0}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.form-grid label{display:grid;gap:5px;font-size:.9rem}.form-grid input,.form-grid select,.form-grid textarea{width:100%;min-width:0;padding:10px;border:1px solid var(--border);border-radius:9px;background:var(--bg);color:var(--text)}.muted{color:var(--muted)}.pill{display:inline-block;padding:4px 8px;border-radius:7px;background:var(--surface-2);font-size:.8rem}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.branch-filter{display:flex;align-items:center;gap:8px;font-size:.9rem;color:var(--muted)}.branch-filter select{max-width:min(280px,48vw);padding:9px 10px;border:1px solid var(--border);border-radius:10px;background:var(--surface);color:var(--text)}.filter-context{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}.finance-note{padding:12px 14px;background:var(--surface-2);border-radius:12px;color:var(--muted)}.mini-actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:900px){.finance-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.finance-grid,.form-grid{grid-template-columns:1fr}}';document.head.append(s)}
function deviceCompleteness(d){const m=[];if(!String(d.serial||'').trim())m.push('Seriale');if(!String(d.type||'').trim()||!String(d.model||'').trim())m.push('Tipologia/modello');if(['Operativo','Assegnato','In consegna'].includes(d.status)&&!d.branchId)m.push('Filiale');if(['Telefono IP','Telefono cordless','Smartphone'].includes(d.type)&&['Operativo','Assegnato'].includes(d.status)&&!String(d.assignedTo||'').trim())m.push('Assegnatario');if(d.status==='Operativo'&&!d.activationDate)m.push('Data attivazione');return m}
async function devicesManagePage(){
 const rows=db.devices.map(d=>({d,missing:deviceCompleteness(d)})).filter(x=>x.missing.length);
 let alerts=[];
 if(window.AssetClientAuth?.user?.role==='admin'){try{const a=await window.AssetClientAuth.api('/api/admin/webex/alerts');alerts=(a.alerts||[]).filter(x=>x.status!=='resolved')}catch{}}
 const assetRows=rows.map(({d,missing})=>`<tr><td>${esc(d.serial||'—')}</td><td>${esc([d.brand,d.model||d.type].filter(Boolean).join(' '))}</td><td>${esc(branchName(d.branchId))}</td><td>${missing.map(x=>'<span class="pill">'+esc(x)+'</span>').join(' ')}</td><td><button data-edit="${d.id}">Completa dati</button></td></tr>`).join('');
 const webexRows=alerts.map(x=>`<tr><td>${esc(x.serialNumber||'—')}</td><td>${esc(x.product||'Dispositivo Webex')} · ${esc(x.displayName||x.webexDeviceId)}</td><td>${esc(x.personEmail||x.workspaceName||x.workspaceId||'Da associare')}</td><td><span class="pill">${x.alertType==='unknown_serial'?'Seriale non censito':'Seriale non disponibile'}</span></td><td><button data-goto="admin-webex">Apri avviso</button></td></tr>`).join('');
 const empty=rows.length||alerts.length?'':'<tr><td colspan="5">Nessun dispositivo da gestire.</td></tr>';
 return `<section class="card"><div class="section-head"><h4>Device da gestire (${rows.length+alerts.length})</h4><span class="muted">Dati incompleti e anomalie da verificare</span></div><p class="muted">Completa i dati mancanti sui cespiti esistenti. I dispositivi in magazzino possono restare senza filiale o assegnatario. Le anomalie Webex sono incluse per gli amministratori dopo una sincronizzazione riuscita.</p><div style="overflow:auto"><table><thead><tr><th>Seriale</th><th>Dispositivo</th><th>Filiale / assegnazione</th><th>Problema</th><th>Azioni</th></tr></thead><tbody>${assetRows}${webexRows}${empty}</tbody></table></div></section>`;
}
async function adminSystemPage(){const r=await window.AssetClientAuth.api('/api/admin/system-status'),checks=r.checks||[],labels={ok:'OK',warning:'Attenzione',error:'Errore',unknown:'Non disponibile'},cls={ok:'ok',warning:'warn',error:'bad',unknown:'muted'};return '<section class="card"><div class="section-head"><h4>Stato sistema</h4><button class="btn-secondary" id="refreshSystem">Aggiorna controlli</button></div><p class="muted">Ultimo controllo: '+esc(new Date(r.checkedAt).toLocaleString('it-IT'))+'. I controlli sono in sola lettura.</p><div class="finance-grid">'+checks.map(x=>'<article class="card"><h4>'+esc(x.label)+'</h4><div class="metric '+(cls[x.status]||'muted')+'">'+esc(labels[x.status]||x.status)+'</div><p>'+esc(x.message)+'</p>'+(x.details?.usedPercent!=null?'<p class="muted">Utilizzo disco: '+esc(x.details.usedPercent)+'% · Disponibile: '+esc((x.details.availableBytes/1024/1024/1024).toFixed(1))+' GB</p>':'')+(x.details?.latencyMs!=null?'<p class="muted">Latenza: '+esc(x.details.latencyMs)+' ms</p>':'')+(x.details?.recordsRead!=null?'<p class="muted">Dispositivi letti: '+esc(x.details.recordsRead)+'</p>':'')+'</article>').join('')+'</div></section><section class="card"><h4>Dettagli recenti</h4><p class="muted">Credenziali e stringhe di connessione non vengono mostrate. Se una metrica non è esposta dall’ambiente, viene indicata come non disponibile.</p><pre style="white-space:pre-wrap;overflow:auto">'+esc(JSON.stringify(checks.map(x=>({controllo:x.label,stato:labels[x.status]||x.status,verifica:x.checkedAt,dettagli:x.details||{}})),null,2))+'</pre></section>'}
async function adminWebexPage(){const [s,a]=await Promise.all([window.AssetClientAuth.api('/api/admin/webex/status'),window.AssetClientAuth.api('/api/admin/webex/alerts')]);const run=s.lastRun,alerts=a.alerts||[];return '<section class="card"><div class="section-head"><h4>Connettore Webex — sola lettura</h4><div class="mini-actions"><button class="btn-secondary" id="reloadWebex">Aggiorna stato</button><button class="btn-primary" id="syncWebex" '+(!s.configured?'disabled':'')+'>Sincronizza ora</button></div></div><p>'+(s.configured?'<span class="badge ok">Token configurato</span>':'<span class="badge warn">Non configurato</span>')+'</p><p class="muted">'+esc(s.message||'La sincronizzazione legge i dispositivi Webex senza modificarli.')+'</p><div class="finance-grid"><article class="card"><h4>Dispositivi rilevati</h4><div class="metric">'+esc(s.deviceCount)+'</div></article><article class="card"><h4>Ultima sincronizzazione</h4><div class="metric" style="font-size:1.15rem">'+esc(run?.status||'Mai eseguita')+'</div><p class="muted">'+esc(run?.finished_at?new Date(run.finished_at).toLocaleString('it-IT'):'Nessuna esecuzione')+'</p></article><article class="card"><h4>Record letti</h4><div class="metric">'+esc(run?.records_read??'—')+'</div></article><article class="card"><h4>Avvisi aperti</h4><div class="metric">'+alerts.filter(x=>x.status!=='resolved').length+'</div></article></div></section><section class="card"><div class="section-head"><h4>Dispositivi da verificare ('+alerts.filter(x=>x.status!=='resolved').length+')</h4><select id="webexAlertFilter"><option value="">Tutti gli stati</option><option value="new">Nuovi</option><option value="acknowledged">Presi in carico</option><option value="resolved">Risolti</option></select></div><p class="muted">Gli avvisi vengono generati solo dopo una sincronizzazione completa. Nessun cespite viene creato o modificato automaticamente.</p><div style="overflow:auto"><table><thead><tr><th>Seriale</th><th>Modello</th><th>Nome Webex</th><th>Utente / workspace</th><th>Stato</th><th>Azioni</th></tr></thead><tbody>'+(alerts.length?alerts.map(x=>'<tr data-alert-row="'+x.id+'" data-alert-status="'+esc(x.status)+'"><td>'+esc(x.serialNumber||'Seriale non disponibile')+'</td><td>'+esc(x.product||'—')+'</td><td>'+esc(x.displayName||x.webexDeviceId)+'</td><td>'+esc(x.personEmail||x.workspaceName||x.workspaceId||'—')+'</td><td>'+esc(x.status)+'</td><td><div class="mini-actions"><button data-alert-status-change="'+x.id+'" data-status="acknowledged">Prendi in carico</button><button data-alert-status-change="'+x.id+'" data-status="resolved">Risolvi</button></div></td></tr>').join(''):'<tr><td colspan="6">Nessun avviso. Se il connettore non è configurato, imposta il token lato server.</td></tr>')+'</tbody></table></div></section>'}
function branchDetailPage(){const b=db.branches.find(x=>x.id===selectedBranchId);if(!b)return '<section class="card"><h4>Filiale non selezionata</h4><button data-goto="branches">Torna alle filiali</button></section>';const ds=db.devices.filter(d=>d.branchId===b.id);return '<section class="card"><div class="section-head"><div><h4>'+esc((b.ragioneSociale?b.ragioneSociale+' — ':'')+b.name)+'</h4><p class="muted">Scheda filiale · fonte anagrafica: NETWORK</p></div><div class="mini-actions"><button class="btn-secondary" data-goto="branches">Torna alle filiali</button><button class="btn-primary" data-edit="'+b.id+'">Modifica filiale</button></div></div><div class="finance-tabs" role="tablist"><button type="button" class="active" data-branch-tab="details" role="tab">Dettagli</button><button type="button" data-branch-tab="devices" role="tab">Dispositivi ('+ds.length+')</button><button type="button" data-branch-tab="checklist" role="tab">Checklist</button></div><section data-branch-panel="details" class="card"><div class="finance-grid"><div><span class="muted">Codice</span><p><b>'+esc(b.code||'—')+'</b></p></div><div><span class="muted">Città / nome</span><p><b>'+esc(b.city||b.name||'—')+'</b></p></div><div><span class="muted">Prefisso telefonico</span><p><b>'+esc(b.phonePrefix||'—')+'</b></p></div><div><span class="muted">LAN</span><p><b>'+esc(b.networkLan||'—')+'</b></p></div></div></section><section data-branch-panel="devices" class="card" hidden>'+deviceRows(ds,false,false)+'</section><section data-branch-panel="checklist" class="card" hidden><div class="section-head"><h4>Checklist tecnici</h4><span class="badge">In attesa del modello</span></div><div style="padding:32px 12px;text-align:center"><div style="font-size:2rem">☑</div><p><b>Nessuna checklist inserita</b></p><p class="muted">Lo spazio è pronto. I contenuti verranno aggiunti quando sarà fornita la checklist utilizzata dai tecnici.</p></div></section></section>'}
function setupBranchTabs(w){if(page!=='branch-detail')return;const tabs=w.querySelectorAll('[data-branch-tab]');const activate=id=>{tabs.forEach(b=>{const on=b.dataset.branchTab===id;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))});w.querySelectorAll('[data-branch-panel]').forEach(p=>p.hidden=p.dataset.branchPanel!==id)};tabs.forEach(b=>b.addEventListener('click',()=>activate(b.dataset.branchTab)))}
function nav(){let n=$('.nav');let items=[['dashboard','Dashboard','01'],['branches','Filiali','02'],['devices','Dispositivi','03'],['devices-manage','Device da gestire','04'],['finance','Finance','05']];if(window.AssetClientAuth?.user?.role==='admin'){items.push(['admin-users','Utenti','06']);items.push(['admin-audit','Audit','07']);items.push(['admin-system','Stato sistema','08']);items.push(['admin-webex','Connettore Webex','09']);}n.innerHTML=items.map(x=>'<a href="#" data-page="'+x[0]+'" class="'+(page===x[0]?'active':'')+'"><span>'+x[1]+'</span><small>'+x[2]+'</small></a>').join('');n.querySelectorAll('a').forEach(a=>a.onclick=e=>{e.preventDefault();page=a.dataset.page;query='';deviceFilter='';render()})}
function deviceRows(rows,actions=true,showCost=true){return '<div style="overflow:auto"><table><thead><tr><th>Matricola</th><th>Apparato</th><th>Filiale</th><th>Stato</th>'+(showCost?'<th>Acquisto</th>':'')+'<th>Attivazione</th>'+(actions?'<th>Azioni</th>':'')+'</tr></thead><tbody>'+(rows.length?rows.map(d=>'<tr><td>'+esc(d.serial)+'</td><td><div class="device-cell"><b>'+esc([d.brand,d.model].filter(Boolean).join(' ')||d.type)+'</b>'+deviceBadge(d.type)+'</div></td><td>'+esc(branchName(d.branchId))+'</td><td>'+statusBadge(d.status)+'</td>'+(showCost?'<td>'+money(d.purchaseCost)+'</td>':'')+'<td>'+esc(d.activationDate||'Non attivato')+'</td>'+(actions?'<td><button data-edit="'+d.id+'">Modifica</button> <button data-del="'+d.id+'">Elimina</button></td>':'')+'</tr>').join(''):'<tr><td colspan="'+(5+(showCost?1:0)+(actions?1:0))+'">Nessun dispositivo presente.</td></tr>')+'</tbody></table></div>'}
function dashboard(){let phones=db.devices.filter(d=>['Telefono IP','Telefono cordless','Smartphone'].includes(d.type)).length,broken=db.devices.filter(d=>d.status==='Guasto').length,manage=db.devices.filter(d=>deviceCompleteness(d).length).length;return '<section class="hero"><div><span class="badge">Inventario operativo</span><h3>Asset e dispositivi per filiale</h3><p>Panoramica operativa di filiali, telefoni e guasti aperti.</p><div class="actions"><button class="btn-primary" data-goto="devices">Nuovo dispositivo</button><button class="btn-secondary" data-goto="branches">Apri filiali</button></div></div></section><section class="finance-grid"><article class="card dashboard-link" role="button" tabindex="0" data-goto="branches" aria-label="Apri elenco filiali"><h4>Filiali</h4><div class="metric">'+db.branches.length+'</div><p class="muted">Apri anagrafica filiali →</p></article><article class="card dashboard-link" role="button" tabindex="0" data-goto="devices" data-filter="phones" aria-label="Apri telefoni"><h4>Telefoni</h4><div class="metric">'+phones+'</div><p class="muted">IP, cordless e smartphone →</p></article><article class="card dashboard-link" role="button" tabindex="0" data-goto="devices" data-filter="broken" aria-label="Apri guasti aperti"><h4>Guasti aperti</h4><div class="metric">'+broken+'</div><p class="muted">Apri dispositivi guasti →</p></article></section><section class="finance-grid"><article class="card dashboard-link" role="button" tabindex="0" data-goto="devices-manage" aria-label="Apri device da gestire"><h4>Device da gestire</h4><div class="metric">'+manage+'</div><p class="muted">Informazioni da completare →</p></article></section><section class="card"><div class="section-head"><h4>Ultimi apparati registrati</h4><button data-goto="devices">Tutti i dispositivi</button></div>'+deviceRows(db.devices.slice(-6).reverse(),false,false)+'</section><p class="footer-note">Finance è disponibile nella sezione dedicata. I dati sono salvati nel browser corrente; per uso multiutente serve un backend con autenticazione.</p>'}
function branchesPage(){let rows=db.branches.filter(b=>Object.values(b).some(v=>String(v??'').toLowerCase().includes(query.toLowerCase())));return '<section class="card"><div class="section-head"><h4>Filiali ('+db.branches.length+')</h4><div class="mini-actions"><input id="search" type="search" placeholder="Cerca filiale, ragione sociale, prefisso..." value="'+esc(query)+'"><button class="btn-secondary" id="importBranches">Importa CSV NETWORK</button><input hidden type="file" id="csvFile" accept=".csv,text/csv"><button class="btn-primary" id="new">+ Nuova filiale</button></div></div><div class="finance-note">Importa un CSV esportato dal foglio NETWORK. Ragione sociale e nome paese sono campi separati.</div><div style="overflow:auto"><table><thead><tr><th>Ragione sociale</th><th>Nome paese</th><th>Prefisso</th><th>LAN</th><th>WLC</th><th>Azioni</th></tr></thead><tbody>'+(rows.length?rows.map(b=>'<tr><td><b>'+esc(b.ragioneSociale||'')+'</b></td><td>'+esc(b.name)+'</td><td>'+esc(b.phonePrefix)+'</td><td>'+esc(b.networkLan)+'</td><td>'+esc(b.wlc)+'</td><td><button data-edit="'+b.id+'">Modifica</button> <button data-del="'+b.id+'">Elimina</button></td></tr>').join(''):'<tr><td colspan="6">Nessuna filiale. Importa il CSV NETWORK per caricare l’anagrafica.</td></tr>')+'</tbody></table></div></section>'}
function devicesPage(){let rows=db.devices.filter(d=>{let matchesBranch=!selectedBranchId||d.branchId===selectedBranchId;let matchesFilter=deviceFilter==='phones'?['Telefono IP','Telefono cordless','Smartphone'].includes(d.type):deviceFilter==='broken'?d.status==='Guasto':true;return matchesBranch&&matchesFilter&&Object.values(d).some(v=>String(v??'').toLowerCase().includes(query.toLowerCase()))}),heading=deviceFilter==='phones'?'Telefoni':deviceFilter==='broken'?'Guasti aperti':'Dispositivi';return '<section class="card"><div class="section-head"><h4>'+heading+' ('+rows.length+(rows.length!==db.devices.length?' di '+db.devices.length:'')+')</h4><div class="mini-actions"><input id="search" type="search" placeholder="Cerca..." value="'+esc(query)+'">'+(deviceFilter?'<button class="btn-secondary" id="clearDeviceFilter">Mostra tutti</button>':'')+'<button class="btn-primary" id="new">+ Nuovo dispositivo</button></div></div>'+deviceRows(rows)+'</section>'}
function finance(){
 const branches=db.branches.filter(b=>!selectedBranchId||b.id===selectedBranchId);
 const scopedDevices=db.devices.filter(d=>!selectedBranchId||d.branchId===selectedBranchId);
 const active=scopedDevices.filter(d=>d.activationDate&&d.branchId&&d.status!=='Dismesso');
 const revenue=branches.reduce((sum,b)=>sum+Math.max(0,Number(b.monthlyRevenue)||0),0);
 const investment=scopedDevices.filter(d=>!d.lotId).reduce((sum,d)=>sum+Math.max(0,Number(d.purchaseCost)||0),0)
   +(selectedBranchId?0:db.purchases.reduce((sum,p)=>sum+Math.max(0,Number(p.totalCost)||0),0));
 const configuredLicenseFee=Math.max(0,Number(db.settings.monthlyLicenseFee)||0);
 const allocatedLicenseCost=()=>branches.filter(b=>b.licenseFeeActive).reduce((sum,b)=>sum+configuredLicenseFee,0);
 /* legacy allocation records are retained for historical reference but are not used for monthly costs */
 const legacyAllocatedLicenseCost=()=>db.licenseAllocations.reduce((sum,a)=>{
   const purchase=db.licensePurchases.find(p=>p.id===a.purchaseId);
   if(!purchase||!a.branchId||(selectedBranchId&&a.branchId!==selectedBranchId))return sum;
   const now=new Date(dateNow()),start=new Date(purchase.startDate),expiry=new Date(purchase.expiryDate);
   if(!purchase.startDate||!purchase.expiryDate||now<start||now>expiry)return sum;
   const term=Math.max(1,Math.round((expiry-start)/(1000*60*60*24*30.4375)));
   const share=Math.min(Number(a.quantity)||0,Number(purchase.quantity)||0)/Math.max(1,Number(purchase.quantity)||1);
   return sum+(Math.max(0,Number(purchase.totalCost)||0)*share/term);
 },0);
 const licenseMonthly=allocatedLicenseCost();
 const deviceMonthlyCost=scopedDevices.filter(d=>d.branchId&&d.status!=='Dismesso').reduce((sum,d)=>sum+Math.max(0,Number(d.purchaseCost)||0)/Math.max(1,Number(d.usefulLifeMonths)||36),0);
 const monthlyCosts=licenseMonthly+deviceMonthlyCost;
 const margin=revenue-monthlyCosts;
 const licenseCash=selectedBranchId?0:db.licensePurchases.reduce((sum,p)=>sum+Math.max(0,Number(p.totalCost)||0),0);
 const licenseRows=db.licensePurchases.map(p=>{
   const allocated=db.licenseAllocations.filter(a=>a.purchaseId===p.id).reduce((sum,a)=>sum+(Number(a.quantity)||0),0);
   return '<tr><td>'+esc(p.category==='webex'?'Webex':'Router')+'</td><td>'+esc(p.packageName)+'</td><td>'+p.quantity+'</td><td>'+money(p.totalCost)+'</td><td>'+esc(p.purchaseDate||'—')+'</td><td>'+esc(p.startDate||'—')+' → '+esc(p.expiryDate||'—')+'</td><td>'+allocated+' / '+p.quantity+'</td></tr>';
 }).join('');
 const branchRows=branches.map(b=>{
   const ds=db.devices.filter(d=>d.branchId===b.id&&d.status!=='Dismesso');
   const allocated=(b.licenseFeeActive?configuredLicenseFee:0);/* Legacy per-license allocation is intentionally not used. */ const legacyAllocated=db.licenseAllocations.reduce((sum,a)=>{
     if(a.branchId!==b.id)return sum;
     const p=db.licensePurchases.find(x=>x.id===a.purchaseId);
     if(!p)return sum;
     const now=new Date(dateNow()),start=new Date(p.startDate),expiry=new Date(p.expiryDate);
     if(!p.startDate||!p.expiryDate||now<start||now>expiry)return sum;
     const term=Math.max(1,Math.round((expiry-start)/(1000*60*60*24*30.4375)));
     return sum+Math.max(0,Number(p.totalCost)||0)*(Math.min(Number(a.quantity)||0,Number(p.quantity)||0)/Math.max(1,Number(p.quantity)||1))/term;
   },0);
   const deviceCost=ds.reduce((sum,d)=>sum+Math.max(0,Number(d.purchaseCost)||0)/Math.max(1,Number(d.usefulLifeMonths)||36),0);
   const rev=Math.max(0,Number(b.monthlyRevenue)||0);
   return '<tr><td>'+esc((b.ragioneSociale?b.ragioneSociale+' — ':'')+b.name)+'</td><td>'+money(rev)+'</td><td>'+money(allocated)+'</td><td>'+money(deviceCost)+'</td><td><b>'+money(rev-allocated-deviceCost)+'</b></td><td><button data-revenue="'+b.id+'">Imposta canone</button> <button data-license-toggle="'+b.id+'">'+(b.licenseFeeActive?'Disattiva canone licenze':'Attiva canone licenze')+'</button></td></tr>';
 }).join('');
 return (selectedBranchId?'<div class="filter-context"><span class="pill">Finance filtrato per: '+esc(branchName(selectedBranchId))+'</span><span class="muted">Il canone licenze viene applicato solo alle filiali in cui è attivo.</span></div>':'')+
 '<section class="finance-grid"><article class="card"><h4>Ricavi fissi mensili</h4><div class="metric">'+money(revenue)+'</div></article><article class="card"><h4>Costi licenze allocati / mese</h4><div class="metric">'+money(licenseMonthly)+'</div></article><article class="card"><h4>Costi hardware ammortizzati / mese</h4><div class="metric">'+money(deviceMonthlyCost)+'</div></article><article class="card"><h4>Margine mensile stimato</h4><div class="metric" style="color:'+(margin<0?'var(--danger, #b42318)':'inherit')+'">'+money(margin)+'</div></article></section>'+
 '<section class="card"><h4>Ricavi fissi e margine per filiale</h4><p class="muted">Il ricavo deriva dal canone fisso della filiale, indipendentemente dal numero di telefoni o licenze. Le licenze aggiuntive non generano ricavi extra.</p><div style="overflow:auto"><table><thead><tr><th>Filiale</th><th>Ricavo fisso/mese</th><th>Canone licenze/mese</th><th>Hardware ammortizzato/mese</th><th>Margine stimato/mese</th><th>Canone</th></tr></thead><tbody>'+branchRows+'</tbody></table></div></section>'+
 '<section class="card"><h4>Riepilogo costi e cassa</h4><div class="finance-grid"><div><p class="muted">Investimento hardware registrato</p><b>'+money(investment)+'</b></div><div><p class="muted">Acquisti licenze (cassa, totale)</p><b>'+(selectedBranchId?'Visualizza su Tutte le filiali':money(licenseCash))+'</b></div><div><p class="muted">Costi ricorrenti allocati/mese</p><b>'+money(licenseMonthly)+'</b></div><div><p class="muted">Margine annualizzato stimato</p><b>'+money(margin*12)+'</b></div></div><p class="footer-note">La cassa registra il costo del pacchetto licenze una sola volta. Il costo gestionale mensile viene ripartito sulla durata residua del contratto e sulle quantità allocate alle filiali. L’hardware è ammortizzato sulla vita utile registrata. Noleggi, costi operativi e sostituzioni devono essere registrati esplicitamente per essere inclusi.</p></section>'+
 '<section class="card"><h4>Registra acquisto licenze Webex / router</h4><p class="muted">Inserisci il costo complessivo del pacchetto e le date effettive. Per co-term, la durata fino alla scadenza comune determina il costo mensile allocabile.</p><form id="licenseForm" class="form-grid"><label>Categoria<select name="category"><option value="webex">Licenze Webex</option><option value="router">Licenze router</option></select></label><label>Nome pacchetto<input name="packageName" required placeholder="Es. Webex Calling EA"></label><label>Quantità acquistata<input name="quantity" type="number" min="1" required value="1"></label><label>Costo totale (€)<input name="totalCost" type="number" min="0" step=".01" required></label><label>Data acquisto<input name="purchaseDate" type="date" required value="'+dateNow()+'"></label><label>Inizio validità<input name="startDate" type="date" required value="'+dateNow()+'"></label><label>Scadenza comune<input name="expiryDate" type="date" required></label><label>Riferimento ordine / contratto<input name="reference"></label><div><button class="btn-primary" type="submit">Registra acquisto licenze</button></div></form></section>'+
 '<section class="card"><h4>Canone mensile licenze per filiale</h4><p class="muted">Imposta qui l’importo mensile da applicare. Poi usa il pulsante nella tabella per attivarlo o disattivarlo su ciascuna filiale. Nessuna quantità di licenze da allocare.</p><form id="licenseFeeSettingsForm" class="form-grid"><label>Importo mensile per filiale (€)<input name="monthlyLicenseFee" type="number" min="0" step=".01" required value="'+esc(db.settings.monthlyLicenseFee??'')+'" placeholder="Inserisci l’importo"></label><div><button class="btn-primary" type="submit">Salva importo</button></div></form></section>'+
 '<section class="card"><h4>Pacchetti licenze registrati</h4><div style="overflow:auto"><table><thead><tr><th>Categoria</th><th>Pacchetto</th><th>Quantità</th><th>Costo cassa</th><th>Acquisto</th><th>Validità</th><th>Allocato</th></tr></thead><tbody>'+(licenseRows||'<tr><td colspan="7">Nessun acquisto licenze registrato.</td></tr>')+'</tbody></table></div></section>';
}
function branchForm(id){let b=id?db.branches.find(x=>x.id===id):{};showModal('Filiale', [['ragioneSociale','Ragione sociale','text',true],['name','Nome paese','text',true],['code','Codice filiale','text'],['city','Città','text'],['phonePrefix','Phone prefix','text'],['networkLan','Network LAN','text'],['wlc','WLC','text'],['oldName','Vecchio nome','text'],['newName','Nuovo nome','text'],['monthlyRevenue','Canone fisso mensile (€)','number']],b,obj=>{obj.monthlyRevenue=Math.max(0,Number(obj.monthlyRevenue)||0);if(id)Object.assign(b,obj);else db.branches.push({id:uid(),...obj});save();render()})}
function deviceForm(id){let d=id?db.devices.find(x=>x.id===id):{};showModal('Dispositivo', [['serial','Matricola / seriale','text',true],['type','Tipologia','select:'+Object.keys(typeDefaults).join('|'),true],['brand','Marca','text'],['model','Modello','text'],['status','Stato','select:Disponibile|Assegnato|Operativo|In consegna|In riparazione|Guasto|Dismesso',true],['branchId','Filiale','branch'],['assignedTo','Assegnato a','text'],['purchaseCost','Costo acquisto (€)','number'],['purchaseDate','Data acquisto','date'],['activationDate','Data attivazione (inizio noleggio)','date'],['monthlyFee','Canone mensile (€)','number'],['usefulLifeMonths','Vita utile / ammortamento (mesi)','number'],['replacedFrom','Sostituisce matricola','text'],['notes','Note','text']],d,obj=>{obj.purchaseCost=Number(obj.purchaseCost)||0;obj.monthlyFee=Number(obj.monthlyFee)||0;obj.usefulLifeMonths=Number(obj.usefulLifeMonths)||36;if(id)Object.assign(d,obj);else db.devices.push({id:uid(),...obj,lotId:''});save();render()})}
function showModal(title,fields,item,onSave){let m=$('#assetModal');if(!m){m=document.createElement('div');m.id='assetModal';m.style.cssText='position:fixed;inset:0;background:#0008;display:grid;place-items:center;padding:16px;z-index:99';document.body.append(m)}let html=fields.map(([k,label,type,req])=>{let val=item[k]??(k==='monthlyFee'?(typeDefaults[item.type]??0):k==='status'?'Disponibile':k==='type'?'Telefono cordless':'');if(type==='branch')return '<label>'+label+'<select name="'+k+'"><option value="">Magazzino / non assegnato</option>'+sortedBranches().map(b=>'<option value="'+b.id+'" '+(val===b.id?'selected':'')+'>'+esc((b.ragioneSociale?b.ragioneSociale+' — ':'')+b.name)+'</option>').join('')+'</select></label>';if(type.startsWith('select:'))return '<label>'+label+'<select name="'+k+'" '+(req?'required':'')+'>'+type.slice(7).split('|').sort((a,b)=>a.localeCompare(b,'it',{sensitivity:'base'})).map(o=>'<option '+(val===o?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select></label>';return '<label>'+label+'<input name="'+k+'" type="'+type+'" value="'+esc(val)+'" '+(req?'required':'')+(type==='number'?' step=".01"':'')+'></label>'}).join('');m.innerHTML='<form id="modalForm" class="card" style="width:min(760px,100%);max-height:90vh;overflow:auto;display:grid;gap:16px"><h2>'+ (item.id?'Modifica ':'Nuova ')+title.toLowerCase()+'</h2><div class="form-grid">'+html+'</div><div class="mini-actions" style="justify-content:flex-end"><button type="button" id="cancel">Annulla</button><button class="btn-primary">Salva</button></div></form>';$('#cancel').onclick=()=>m.remove();$('#modalForm').onsubmit=e=>{e.preventDefault();let o={};for(const [k] of fields)o[k]=new FormData(e.target).get(k)||'';onSave(o);m.remove()}}
function del(id){if(!confirm('Confermi eliminazione?'))return;if(page==='branches'){db.branches=db.branches.filter(x=>x.id!==id);db.devices.forEach(d=>{if(d.branchId===id)d.branchId=''})}else db.devices=db.devices.filter(x=>x.id!==id);save();render()}
function importCsv(text){let lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean),parse=l=>l.split(';').map(x=>x.trim().replace(/^"|"$/g,'').replace(/""/g,'"'));let h=parse(lines.shift()).map(x=>x.toLowerCase());let ix=(...names)=>h.findIndex(x=>names.includes(x.toLowerCase()));let indexes={name:ix('ragione sociale','nome filiale','filiale'),phonePrefix:ix('phone prefix','prefisso'),networkLan:ix('network lan'),wlc:ix('wlc'),oldName:ix('vecchio nome'),newName:ix('nuovo nome'),code:ix('codice','code'),city:ix('città','citta')};if(indexes.name<0)throw Error('Colonna RAGIONE SOCIALE non trovata: esporta il foglio NETWORK con intestazioni.');let added=0,updated=0;for(const line of lines){let a=parse(line),combined=a[indexes.name];if(!combined)continue;let split=splitBranchName(combined),obj={ragioneSociale:split.ragioneSociale,name:split.name};for(let k in indexes)if(k!=='name')obj[k]=indexes[k]>=0?(a[indexes[k]]||''):'';let old=db.branches.find(b=>b.name.toLowerCase()===split.name.toLowerCase()&&String(b.ragioneSociale||'').toLowerCase()===split.ragioneSociale.toLowerCase())||db.branches.find(b=>b.name.toLowerCase()===combined.toLowerCase());if(old){Object.assign(old,obj);updated++}else{db.branches.push({id:uid(),...obj});added++}}save();alert('Importazione completata: '+added+' nuove filiali, '+updated+' aggiornate.');render()}
function ensureBranchFilter(){let top=$('.topbar .actions');if(!top)return;let wrap=$('#globalBranchFilter');if(!wrap){wrap=document.createElement('label');wrap.id='globalBranchFilter';wrap.className='branch-filter';wrap.innerHTML='<span>Filiale</span><select id="globalBranchSelect" aria-label="Filtra per filiale"><option value="">Tutte le filiali</option></select>';top.insertBefore(wrap,top.firstChild)}let select=$('#globalBranchSelect');if(!select)return;let options='<option value="">Tutte le filiali</option>'+db.branches.slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),'it')).map(b=>'<option value="'+esc(b.id)+'">'+esc((b.ragioneSociale?b.ragioneSociale+' — ':'')+b.name)+'</option>').join('');if(select.innerHTML!==options)select.innerHTML=options;select.value=selectedBranchId;select.onchange=()=>{selectedBranchId=select.value;query='';render()}}
async function adminUsersPage(){const r=await window.AssetClientAuth.api('/api/admin/users');const users=r.users||[];return '<section class="card"><div class="section-head"><h4>Nuovo utente</h4><span class="muted">Crea account e assegna il ruolo</span></div><form id="adminCreateUser" class="form-grid"><label>Username<input name="username" required minlength="3" maxlength="64" pattern="[a-zA-Z0-9._-]+" autocomplete="off"></label><label>Password iniziale<input name="password" type="password" required minlength="12" autocomplete="new-password"></label><label>Ruolo<select name="role"><option value="operator">Operatore</option><option value="admin">Amministratore</option></select></label><div style="align-self:end"><button class="btn-primary" type="submit">Crea utente</button></div></form><p class="muted">La password deve contenere almeno 12 caratteri.</p></section><section class="card"><div class="section-head"><h4>Utenti e permessi ('+users.length+')</h4><button class="btn-secondary" id="reloadUsers">Aggiorna</button></div><div style="overflow:auto"><table><thead><tr><th>Utente</th><th>Ruolo</th><th>Stato</th><th>Ultimo accesso</th><th>Modifiche</th></tr></thead><tbody>'+users.map(u=>'<tr><td><b>'+esc(u.username)+'</b></td><td><select data-role-user="'+u.id+'"><option value="operator" '+(u.role==='operator'?'selected':'')+'>Operatore</option><option value="admin" '+(u.role==='admin'?'selected':'')+'>Amministratore</option></select></td><td><span class="badge '+(u.active?'ok':'bad')+'">'+(u.active?'Attivo':'Disattivato')+'</span></td><td>'+esc(u.last_login_at?new Date(u.last_login_at).toLocaleString('it-IT'):'Mai')+'</td><td><div class="mini-actions"><button class="btn-secondary" data-save-user="'+u.id+'">Salva ruolo</button><button class="btn-secondary" data-toggle-user="'+u.id+'" data-active="'+(!u.active)+'">'+(u.active?'Disattiva':'Attiva')+'</button><form data-password-form="'+u.id+'" class="mini-actions"><input type="password" name="password" placeholder="Nuova password" minlength="12" required aria-label="Nuova password per '+esc(u.username)+'"><button class="btn-secondary" type="submit">Reimposta</button></form></div></td></tr>').join('')+'</tbody></table></div><p class="muted">Gli operatori gestiscono l’inventario; solo gli amministratori possono gestire gli account.</p></section>'}async function adminAuditPage(){const r=await window.AssetClientAuth.api('/api/admin/audit?limit=200');const events=r.events||[];return '<section class="card"><div class="section-head"><h4>Registro attività</h4><button class="btn-secondary" id="reloadAudit">Aggiorna</button></div><p class="muted">Conservazione: permanente, senza cancellazione automatica. Mostrati gli ultimi '+events.length+' eventi.</p><div style="overflow:auto"><table><thead><tr><th>Data e ora</th><th>Utente</th><th>Azione</th><th>Endpoint</th><th>Esito</th><th>Dettagli</th></tr></thead><tbody>'+events.map(v=>'<tr><td>'+esc(new Date(v.created_at).toLocaleString('it-IT'))+'</td><td>'+esc(v.actor_username||'Utente eliminato')+'</td><td>'+esc(v.action)+'</td><td>'+esc(v.endpoint)+'</td><td>'+esc(v.status_code)+'</td><td><details><summary>Apri</summary><pre style="white-space:pre-wrap;max-width:460px">'+esc(JSON.stringify(v.details||{},null,2))+'</pre></details></td></tr>').join('')+'</tbody></table></div></section>'}
function setupFinanceTabs(w){
 if(page!=='finance')return;
 const panels=[...w.children].filter(el=>el.tagName==='SECTION');
 if(!panels.length)return;
 const tabs=document.createElement('div');tabs.className='finance-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Sezioni Finance');
 const names=[['overview','Panoramica'],['branches','Dettaglio filiali'],['purchases','Acquisti hardware'],['licenses','Licenze']];
 const classify=el=>{
  const h=el.querySelector('h4')?.textContent?.trim()||'';
  if(el.classList.contains('finance-grid'))return 'overview';
  if(h.includes('Ricavi fissi e margine per filiale'))return 'branches';
  if(h.includes('Registra acquisto licenze')||h.includes('Canone mensile licenze')||h.includes('Pacchetti licenze'))return 'licenses';
  if(h.includes('Riepilogo costi e cassa'))return 'overview';
  return 'overview';
 };
 panels.forEach(el=>{el.dataset.financePanel=classify(el);el.classList.add('finance-panel')});
 const hardware=document.createElement('section');hardware.className='card finance-panel';hardware.dataset.financePanel='purchases';
 const purchaseRows=db.purchases.map(p=>'<tr><td>'+esc(p.type||'—')+'</td><td>'+Number(p.quantity||0)+'</td><td>'+money(p.totalCost)+'</td><td>'+esc(p.purchaseDate||'—')+'</td><td>'+money(p.monthlyFee||0)+'</td><td>'+Number(p.usefulLifeMonths||36)+' mesi</td></tr>').join('');
 hardware.innerHTML='<div class="section-head"><h4>Acquisti hardware ('+db.purchases.length+')</h4><button class="btn-secondary" data-goto="devices">Apri inventario dispositivi</button></div><p class="muted">Storico dei lotti hardware registrati. Per inserire un nuovo acquisto apri l’inventario dispositivi e registra un lotto.</p><div style="overflow:auto"><table><thead><tr><th>Categoria</th><th>Quantità</th><th>Costo totale</th><th>Data acquisto</th><th>Canone mensile unitario</th><th>Vita utile</th></tr></thead><tbody>'+(purchaseRows||'<tr><td colspan="6">Nessun acquisto hardware registrato.</td></tr>')+'</tbody></table></div>';
 tabs.innerHTML=names.map(([id,label])=>'<button type="button" role="tab" data-finance-tab="'+id+'">'+label+'</button>').join('');
 w.insertBefore(tabs,w.firstChild);w.append(hardware);
 const activate=id=>{tabs.querySelectorAll('[data-finance-tab]').forEach(b=>{const yes=b.dataset.financeTab===id;b.classList.toggle('active',yes);b.setAttribute('aria-selected',String(yes))});w.querySelectorAll('[data-finance-panel]').forEach(el=>el.hidden=el.dataset.financePanel!==id)};
 tabs.addEventListener('click',e=>{const b=e.target.closest('[data-finance-tab]');if(b)activate(b.dataset.financeTab)});
 activate('overview');
}
function render(){styles();ensureBranchFilter();nav();let titles={dashboard:['Dashboard','Panoramica asset e redditività.'],branches:['Filiali','Anagrafica importata dal foglio NETWORK.'],devices:['Dispositivi','Inventario, assegnazioni, guasti e sostituzioni.'],'devices-manage':['Device da gestire','Dispositivi con informazioni da completare o verificare.'],'branch-detail':['Filiale','Dettagli, dispositivi e checklist della filiale.'],finance:['Finance','Investimenti, canoni, ammortamento e rientro economico.'],'admin-users':['Utenti','Gestione utenti, ruoli e accessi.'],'admin-audit':['Audit','Registro permanente delle modifiche effettuate dagli utenti.'],'admin-system':['Stato sistema','Controlli operativi di applicazione, database, disco e connettori.'],'admin-webex':['Connettore Webex','Sincronizzazione in sola lettura e avvisi sui dispositivi.']};$('.title h2').textContent=titles[page][0];$('.title p').textContent=titles[page][1];let w=$('.wrap');w.innerHTML=page==='dashboard'?dashboard():page==='branches'?branchesPage():page==='devices'?devicesPage():page==='devices-manage'?'<section class="card">Caricamento dispositivi da gestire…</section>':page==='branch-detail'?branchDetailPage():page==='admin-users'?'<section class="card">Caricamento utenti…</section>':page==='admin-audit'?'<section class="card">Caricamento audit…</section>':page==='admin-system'?'<section class="card">Verifica stato sistema…</section>':page==='admin-webex'?'<section class="card">Caricamento connettore Webex…</section>':finance();setupFinanceTabs(w);setupBranchTabs(w);if(page==='devices-manage')devicesManagePage().then(x=>{if(page==='devices-manage')w.innerHTML=x}).catch(e=>{if(page==='devices-manage')w.innerHTML='<section class="card">Errore caricamento coda: '+esc(e.message)+'</section>'});if(page==='admin-users')adminUsersPage().then(x=>{if(page==='admin-users')w.innerHTML=x}).catch(e=>{w.innerHTML='<section class="card">Errore caricamento utenti: '+esc(e.message)+'</section>'});if(page==='admin-audit')adminAuditPage().then(x=>{if(page==='admin-audit')w.innerHTML=x}).catch(e=>{w.innerHTML='<section class="card">Errore caricamento audit: '+esc(e.message)+'</section>'});if(page==='admin-system')adminSystemPage().then(x=>{if(page==='admin-system')w.innerHTML=x}).catch(e=>{w.innerHTML='<section class="card">Errore caricamento controlli: '+esc(e.message)+'</section>'});if(page==='admin-webex')adminWebexPage().then(x=>{if(page==='admin-webex')w.innerHTML=x}).catch(e=>{w.innerHTML='<section class="card">Errore caricamento Webex: '+esc(e.message)+'</section>'});w.onclick=async e=>{let edit=e.target.closest('[data-edit]'),delb=e.target.closest('[data-del]'),go=e.target.closest('[data-goto]'),saveUser=e.target.closest('[data-save-user]'),toggleUser=e.target.closest('[data-toggle-user]');if(saveUser){try{const id=saveUser.dataset.saveUser,role=w.querySelector('[data-role-user="'+id+'"]')?.value;await window.AssetClientAuth.api('/api/admin/users/'+id,{method:'PATCH',body:JSON.stringify({role})});alert('Ruolo aggiornato.');render()}catch(err){alert(err.message)}return}if(toggleUser){try{await window.AssetClientAuth.api('/api/admin/users/'+toggleUser.dataset.toggleUser,{method:'PATCH',body:JSON.stringify({active:toggleUser.dataset.active==='true'})});render()}catch(err){alert(err.message)}return}if(e.target.id==='reloadUsers'){render();return}if(e.target.id==='reloadAudit'){render();return}if(e.target.id==='refreshSystem'){render();return}if(e.target.id==='reloadWebex'){render();return}if(e.target.id==='syncWebex'){try{e.target.disabled=true;const result=await window.AssetClientAuth.api('/api/admin/webex/sync',{method:'POST',body:JSON.stringify({})});alert('Sincronizzazione completata: '+result.recordsRead+' dispositivi letti.');render()}catch(err){alert(err.message);render()}return}let alertChange=e.target.closest('[data-alert-status-change]');if(alertChange){const resolutionReason=alertChange.dataset.status==='resolved'?(prompt('Motivazione della risoluzione (facoltativa):','Verificato dall’amministratore')||''):'';try{await window.AssetClientAuth.api('/api/admin/webex/alerts/'+alertChange.dataset.alertStatusChange,{method:'PATCH',body:JSON.stringify({status:alertChange.dataset.status,resolutionReason})});render()}catch(err){alert(err.message)}return}let openBranch=e.target.closest('[data-open-branch]');if(openBranch){selectedBranchId=openBranch.dataset.openBranch;page='branch-detail';render();return}if(edit){if(page==='branches')branchForm(edit.dataset.edit);else if(page==='branch-detail')branchForm(edit.dataset.edit);else deviceForm(edit.dataset.edit)}if(delb)del(delb.dataset.del);if(go){page=go.dataset.goto;query='';deviceFilter=go.dataset.filter||'';render()}if(e.target.id==='clearDeviceFilter'){deviceFilter='';query='';render()}if(e.target.id==='new'){if(page==='branches')branchForm();else deviceForm()}if(e.target.id==='importBranches')$('#csvFile').click();if(e.target.id==='webexAlertFilter'){w.querySelectorAll('[data-alert-row]').forEach(row=>row.hidden=Boolean(e.target.value)&&row.dataset.alertStatus!==e.target.value)}};w.onchange=e=>{if(e.target.id==='webexAlertFilter')w.querySelectorAll('[data-alert-row]').forEach(row=>row.hidden=Boolean(e.target.value)&&row.dataset.alertStatus!==e.target.value)};w.onsubmit=async e=>{if(e.target.id==='adminCreateUser'){e.preventDefault();const f=new FormData(e.target);try{await window.AssetClientAuth.api('/api/admin/users',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password'),role:f.get('role')})});alert('Utente creato.');render()}catch(err){alert(err.message)}}else if(e.target.matches('[data-password-form]')){e.preventDefault();const f=new FormData(e.target);try{await window.AssetClientAuth.api('/api/admin/users/'+e.target.dataset.passwordForm,{method:'PATCH',body:JSON.stringify({password:f.get('password')})});alert('Password aggiornata.');render()}catch(err){alert(err.message)}}};w.oninput=e=>{if(e.target.id==='search'){query=e.target.value;let pos=e.target.selectionStart;render();let x=$('#search');if(x){x.focus();x.setSelectionRange(pos,pos)}}};w.onkeydown=e=>{let tile=e.target.closest('[data-goto][role="button"]');if(tile&&(e.key==='Enter'||e.key===' ')){e.preventDefault();page=tile.dataset.goto;query='';deviceFilter=tile.dataset.filter||'';render()}};let file=$('#csvFile');if(file)file.onchange=async()=>{if(!file.files[0])return;try{importCsv(await file.files[0].text())}catch(err){alert('Errore importazione: '+err.message)}};let lot=$('#lotForm');let license=$('#licenseForm');if(license)license.onsubmit=e=>{e.preventDefault();let f=new FormData(license),quantity=Math.floor(Number(f.get('quantity'))),totalCost=Number(f.get('totalCost')),startDate=f.get('startDate'),expiryDate=f.get('expiryDate');if(!quantity||quantity<1||totalCost<0||!startDate||!expiryDate||expiryDate<startDate)return alert('Verifica quantità, costo e date di validità.');db.licensePurchases.push({id:uid(),category:f.get('category'),packageName:String(f.get('packageName')).trim(),quantity,totalCost,purchaseDate:f.get('purchaseDate'),startDate,expiryDate,reference:f.get('reference')||''});save();render()};let feeSettings=$('#licenseFeeSettingsForm');if(feeSettings)feeSettings.onsubmit=e=>{e.preventDefault();let value=Number(new FormData(feeSettings).get('monthlyLicenseFee'));if(!Number.isFinite(value)||value<0)return alert('Inserisci un importo valido.');db.settings.monthlyLicenseFee=value;save();render()};let revenueButtons=$('[data-revenue]');if(revenueButtons){}w.onclick=(e)=>{let licenseToggle=e.target.closest('[data-license-toggle]');if(licenseToggle){if(db.settings.monthlyLicenseFee===''||!Number.isFinite(Number(db.settings.monthlyLicenseFee))||Number(db.settings.monthlyLicenseFee)<0){alert('Inserisci e salva prima l’importo mensile del canone licenze.');return;}const b=db.branches.find(x=>x.id===licenseToggle.dataset.licenseToggle);if(b){b.licenseFeeActive=!b.licenseFeeActive;save();render()}return;}let revenueBtn=e.target.closest('[data-revenue]');if(revenueBtn){const branch=db.branches.find(b=>b.id===revenueBtn.dataset.revenue);if(branch){const input=prompt('Canone fisso mensile per '+branch.name+' (€):',String(branch.monthlyRevenue||0));if(input!==null&&input.trim()!==''&&Number.isFinite(Number(input))&&Number(input)>=0){branch.monthlyRevenue=Number(input);save();render()}else if(input!==null)alert('Inserisci un importo valido.');}return;}let edit=e.target.closest('[data-edit]'),delb=e.target.closest('[data-del]'),go=e.target.closest('[data-goto]');if(edit){if(page==='branches')branchForm(edit.dataset.edit);else deviceForm(edit.dataset.edit)}if(delb)del(delb.dataset.del);if(go){page=go.dataset.goto;query='';deviceFilter=go.dataset.filter||'';render()}if(e.target.id==='clearDeviceFilter'){deviceFilter='';query='';render()}if(e.target.id==='new'){if(page==='branches')branchForm();else deviceForm()}if(e.target.id==='importBranches')$('#csvFile').click()};if(lot)lot.onsubmit=e=>{e.preventDefault();let f=new FormData(lot),type=f.get('type'),qty=Math.floor(Number(f.get('quantity'))),cost=Number(f.get('totalCost')),date=f.get('purchaseDate'),fee=f.get('monthlyFee')!==''?Number(f.get('monthlyFee')):type==='Room Bar'?Number(db.settings.roomBarFee)||0:type==='Room Bar Pro'?Number(db.settings.roomBarProFee)||0:(typeDefaults[type]||0);if(!qty||qty<1||cost<0)return alert('Verifica quantità e costo.');let lotId=uid(),p={id:lotId,type,quantity:qty,totalCost:cost,purchaseDate:date,monthlyFee:fee,usefulLifeMonths:Number(f.get('usefulLifeMonths'))||36};db.purchases.push(p);for(let i=1;i<=qty;i++)db.devices.push({id:uid(),serial:'LOT-'+lotId.slice(0,6).toUpperCase()+'-'+String(i).padStart(3,'0'),type,brand:type.includes('Room Bar')?'Cisco':'',model:type, status:'Disponibile',branchId:'',assignedTo:'',purchaseCost:cost/qty,purchaseDate:date,activationDate:'',monthlyFee:fee,usefulLifeMonths:p.usefulLifeMonths,replacedFrom:'',notes:'Creato da lotto '+lotId.slice(0,6),lotId});if(type==='Room Bar'&&f.get('monthlyFee')!=='')db.settings.roomBarFee=fee;if(type==='Room Bar Pro'&&f.get('monthlyFee')!=='')db.settings.roomBarProFee=fee;save();render();alert('Lotto registrato: costo unitario '+money(cost/qty)+'. Assegna i dispositivi alle filiali e imposta la data di attivazione per avviare i canoni.')};let rf=$('#routerForm');if(rf)rf.onsubmit=e=>{e.preventDefault();let f=new FormData(rf);db.devices.push({id:uid(),serial:f.get('serial'),type:'Router',brand:'',model:f.get('model'),status:f.get('activationDate')?'Operativo':f.get('branchId')?'Assegnato':'Disponibile',branchId:f.get('branchId'),assignedTo:'',purchaseCost:Number(f.get('purchaseCost')),purchaseDate:f.get('purchaseDate'),activationDate:f.get('activationDate'),monthlyFee:Number(f.get('monthlyFee')||40),usefulLifeMonths:Number(f.get('usefulLifeMonths')||60),replacedFrom:'',notes:'',lotId:''});save();render()}}
document.addEventListener('click',e=>{if(e.target.id==='themeToggle'){setTimeout(()=>localStorage.setItem('asset-client-theme',document.documentElement.dataset.theme||'light'),0)}});
let savedTheme=localStorage.getItem('asset-client-theme');if(savedTheme)document.documentElement.dataset.theme=savedTheme;
render();
fetch('./network-seed.json').then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(rows=>{
  if(db.settings.networkSeedVersion==='2026-10-09')return;
  let added=0,updated=0;
  for(const row of rows){
    const [name,phonePrefix,networkLan,networkServices,networkGuest,wlc,voice,oldName]=row;
    const split=splitBranchName(name);
    const fields={...split,phonePrefix,networkLan,networkServices,networkGuest,wlc,voice,oldName,newName:''};
    const existing=db.branches.find(b=>String(b.name||'').trim().toLocaleLowerCase('it')===split.name.trim().toLocaleLowerCase('it')&&String(b.ragioneSociale||'').trim().toLocaleLowerCase('it')===split.ragioneSociale.trim().toLocaleLowerCase('it'))||db.branches.find(b=>String(b.name||'').trim().toLocaleLowerCase('it')===name.trim().toLocaleLowerCase('it'));
    if(existing){Object.assign(existing,fields);updated++}
    else{db.branches.push({id:uid(),...fields});added++}
  }
  db.settings.networkSeedVersion='2026-10-09';
  save();
  console.info('NETWORK seed caricato:',added,'nuove filiali,',updated,'aggiornate');
  render();
}).catch(err=>console.error('Caricamento anagrafica NETWORK non riuscito:',err)).finally(()=>loadVideoSeed());
})();